#include <iostream>
int main() {
    int a[3] = {5, 1, 3};
    int t = a[0]; a[0] = a[2]; a[2] = t;
    std::cout << a[0] << a[1] << a[2] << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {5, 1, 4, 2};
    for (int i = 0; i < 3; i++)
        if (a[i] > a[i + 1]) { int t = a[i]; a[i] = a[i + 1]; a[i + 1] = t; }
    for (int x : a) std::cout << x;
    std::cout << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {4, 3, 1, 2}, n = 4, swaps = 0;
    for (int i = 0; i < n - 1; i++)
        if (a[i] > a[i + 1]) { int t = a[i]; a[i] = a[i + 1]; a[i + 1] = t; swaps++; }
    std::cout << swaps << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {2, 4, 1}, key = 1, shifts = 0;
    int j = 2;
    while (j > 0 && a[j - 1] > key) { a[j] = a[j - 1]; j--; shifts++; }
    a[j] = key;
    std::cout << shifts << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {3, 1, 2};
    for (int i = 0; i < 2; i++) {
        int m = i;
        for (int j = i + 1; j < 3; j++) if (a[j] < a[m]) m = j;
        int t = a[i]; a[i] = a[m]; a[m] = t;
    }
    for (int x : a) std::cout << x;
    std::cout << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {3, 1, 2}, n = 3, swaps = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; swaps++; }
    std::cout << swaps << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {3, 2, 1}, n = 3, passes = 0;
    for (bool swapped = true; swapped; ) {
        swapped = false;
        for (int i = 0; i < n - 1; i++)
            if (a[i] > a[i + 1]) { int t = a[i]; a[i] = a[i + 1]; a[i + 1] = t; swapped = true; }
        passes++;
    }
    std::cout << passes << "\n";
    return 0;
}
